(()=>{
const canvas=document.querySelector('#globe'),context=canvas.getContext('2d'),reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const primary=[{key:'germany',name:'Essen, Germany',coordinates:[7.01,51.46],type:'Company office'},{key:'uae',name:'Abu Dhabi, UAE',coordinates:[54.38,24.45],type:'Production & blending facility'}];
let locations=primary,land=null,visible=false,raf=0,last=0,longitude=24,latitude=22,targetLongitude=24,targetLatitude=22,dragging=false,startX=0,startLongitude=24,pauseUntil=0,mode='globe',selected=null,hovered=null,projected=[],moved=false;
const labels=primary.map(l=>document.querySelector('#map-pin-'+l.key)),tooltip=document.querySelector('#map-active-location'),select=document.querySelector('#network-location');
let projection=d3.geoOrthographic().clipAngle(90).precision(.4);const path=d3.geoPath(projection,context),graticule=d3.geoGraticule().step([30,30])();
function fixWinding(f){if(d3.geoArea(f)>2*Math.PI)(f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates).forEach(p=>p.forEach(r=>r.reverse()));return f}
fetch('world-land.json').then(r=>{if(!r.ok)throw Error('map');return r.json()}).then(data=>{data.features.forEach(fixWinding);land=data;start()}).catch(()=>start());
fetch('locations.json').then(r=>{if(!r.ok)throw Error('network');return r.json()}).then(data=>{locations=data;const office=document.createElement('optgroup');office.label='Company locations';const network=document.createElement('optgroup');network.label='Distribution network';[...locations].sort((a,b)=>a.name.localeCompare(b.name)).forEach(l=>{const option=document.createElement('option');option.value=l.key;option.textContent=l.name;(l.type==='Distributor location'?network:office).append(option)});select.append(office,network);document.querySelector('#network-count').textContent=data.filter(l=>l.type==='Distributor location').length+' distribution locations · 2 company locations';start()}).catch(()=>document.querySelector('#network-count').textContent='Network locations could not load. Please refresh.');
function setView(next){mode=next;projection=mode==='globe'?d3.geoOrthographic().clipAngle(90).precision(.4):d3.geoNaturalEarth1().precision(.4);path.projection(projection);document.querySelectorAll('[data-map-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapView===mode)));document.querySelector('.globe-label').textContent=mode==='globe'?'DRAG TO EXPLORE · TAP A LOCATION':'WORLDWIDE NETWORK · TAP A LOCATION';if(mode==='globe'&&selected)focus(selected);start()}
function focus(location){selected=location;hovered=null;select.value=location.key;if(mode==='globe'){targetLongitude=location.coordinates[0];targetLatitude=Math.max(-45,Math.min(45,location.coordinates[1]-8))}pauseUntil=performance.now()+12000;start()}
function draw(time=0){raf=0;if(!visible||document.hidden)return;if(!reducedMotion&&time-last<30){raf=requestAnimationFrame(draw);return}const dt=Math.min(time-last||16,50);last=time;
if(!dragging){longitude+=(targetLongitude-longitude)*Math.min(1,dt*.006);latitude+=(targetLatitude-latitude)*Math.min(1,dt*.006)}
const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio,1.75),r=Math.min(w,h)*.395,cx=w*.5,cy=h*.48;
if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}context.setTransform(dpr,0,0,dpr,0,0);context.clearRect(0,0,w,h);
const gentle=reducedMotion||dragging||time<pauseUntil?0:Math.sin(time*.00008)*5,lon=longitude+gentle;
if(mode==='globe')projection.translate([cx,cy]).scale(r).rotate([-lon,-latitude,0]);else projection.rotate([0,0,0]).fitExtent([[12,65],[w-12,h-50]],{type:'Sphere'});
function front(c){return mode==='world'||d3.geoDistance([lon,latitude],c)<Math.PI/2-.015}
const ocean=context.createRadialGradient(cx-r*.45,cy-r*.5,r*.05,cx+r*.15,cy+r*.15,r*1.3);ocean.addColorStop(0,'#fffbed');ocean.addColorStop(.55,'#f1ead9');ocean.addColorStop(1,'#d3c5a5');context.beginPath();path({type:'Sphere'});context.fillStyle=ocean;context.fill();context.save();context.beginPath();path({type:'Sphere'});context.clip();
context.beginPath();path(graticule);context.strokeStyle='#ac8d3d25';context.lineWidth=.65;context.stroke();
if(land)land.features.forEach(f=>{context.beginPath();path(f);context.fillStyle='#d3b978';context.fill();context.strokeStyle='#f8f4e1aa';context.lineWidth=.55;context.stroke()});
const tint=context.createLinearGradient(cx-r,cy-r,cx+r,cy+r);tint.addColorStop(0,'#ffffff40');tint.addColorStop(.5,'#fffef400');tint.addColorStop(1,'#5c684529');context.fillStyle=tint;context.fillRect(0,0,w,h);context.restore();context.beginPath();path({type:'Sphere'});context.strokeStyle='#b4bda86b';context.lineWidth=.9;context.stroke();
const destination=selected||primary[1],interpolate=d3.geoInterpolate(primary[0].coordinates,destination.coordinates);context.beginPath();let connected=false;for(let i=0;i<=60;i++){const t=i/60,c=interpolate(t),p=projection(c);if(!front(c)){connected=false;continue}const height=mode==='world'?1:1+.09*Math.sin(t*Math.PI),x=cx+(p[0]-cx)*height,y=cy+(p[1]-cy)*height;if(connected)context.lineTo(x,y);else context.moveTo(x,y);connected=true}context.strokeStyle='#9c784488';context.lineWidth=1.2;context.stroke();
projected=[];locations.forEach(location=>{if(!front(location.coordinates))return;const p=projection(location.coordinates);if(!p||!p.every(Number.isFinite))return;projected.push({location,p});const highlight=selected?.key===location.key||hovered?.key===location.key,isOffice=location.type!=='Distributor location';context.beginPath();context.arc(p[0],p[1],highlight?9:isOffice?6:4.5,0,Math.PI*2);context.fillStyle=highlight?'#d8a52255':'#bd995b22';context.fill();context.strokeStyle=highlight?'#b31219':'#c4933680';context.lineWidth=highlight?1.3:.7;context.stroke();context.beginPath();context.arc(p[0],p[1],highlight?3.6:isOffice?2.9:2.2,0,Math.PI*2);context.fillStyle=highlight?'#a20810':'#b31219';context.fill()});
primary.forEach((location,i)=>{const p=projection(location.coordinates),show=front(location.coordinates)&&mode==='globe'&&selected?.key!==location.key&&hovered?.key!==location.key;labels[i].style.display=show?'block':'none';if(show){labels[i].style.left=p[0]+'px';labels[i].style.top=p[1]+'px';labels[i].style.transform=i===0?'translate(calc(-100% - 12px), -50%)':'translate(12px, -50%)'}});
const active=hovered||selected;tooltip.style.display=active&&front(active.coordinates)?'block':'none';if(active&&front(active.coordinates)){const p=projection(active.coordinates);tooltip.replaceChildren();const name=document.createElement('span');name.textContent=active.name;const type=document.createElement('small');type.textContent=active.type;tooltip.append(name,type);tooltip.style.left=Math.max(8,Math.min(w-165,p[0]+12))+'px';tooltip.style.top=Math.max(60,Math.min(h-55,p[1]))+'px';tooltip.style.transform='translateY(-110%)'}
if((mode==='globe'&&!reducedMotion)||Math.abs(longitude-targetLongitude)>.01||Math.abs(latitude-targetLatitude)>.01)raf=requestAnimationFrame(draw)}
function start(){if(!raf&&visible){last=performance.now()-35;raf=requestAnimationFrame(draw)}}
function nearest(e){const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;let closest=null,min=14*14;projected.forEach(({location,p})=>{const d=(p[0]-x)**2+(p[1]-y)**2;if(d<min){min=d;closest=location}});return closest}
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)start();else if(raf){cancelAnimationFrame(raf);raf=0}},{threshold:.08}).observe(canvas);
canvas.addEventListener('pointerdown',e=>{dragging=mode==='globe';moved=false;startX=e.clientX;startLongitude=longitude;canvas.setPointerCapture(e.pointerId);pauseUntil=performance.now()+10000;start()});canvas.addEventListener('pointermove',e=>{if(dragging){if(Math.abs(e.clientX-startX)>4)moved=true;longitude=startLongitude-(e.clientX-startX)*.3;targetLongitude=longitude;start()}else{hovered=nearest(e);canvas.style.cursor=hovered?'pointer':mode==='globe'?'grab':'default';start()}});canvas.addEventListener('pointerup',e=>{dragging=false;if(!moved){const location=nearest(e);if(location)focus(location)}pauseUntil=performance.now()+10000;start()});canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('pointerleave',()=>{hovered=null;start()});
select.addEventListener('change',()=>{const location=locations.find(l=>l.key===select.value);if(location)focus(location);else{selected=null;start()}});document.querySelectorAll('[data-map-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.mapView)));document.querySelectorAll('[data-location]').forEach(b=>b.addEventListener('click',()=>{const location=locations.find(l=>l.key===b.dataset.location);if(location)focus(location)}));
addEventListener('resize',start);document.addEventListener('visibilitychange',()=>{if(document.hidden){if(raf)cancelAnimationFrame(raf);raf=0}else start()});
})();
